/*
  # HEADER #
	Script: 		Common\Functions\Common_GetVehicleTurrets.sqf
	Alias:			CTI_CO_FNC_GetVehicleTurrets
	Description:	Return the vehicle's turret on 2 levels
	Author: 		Benny
	Creation Date:	18-09-2013
	Revision Date:	31-03-2015 (Sari)
					16-10-2026 (VIOC crew_fix, parche de VIOC; no es del autor de la mision)

  # PARAMETERS #
    0	[String/Object]: The vehicle classname

  # RETURNED VALUE #
	[Array]: The vehicle turrets

  # SYNTAX #
	(CLASSNAME) call CTI_CO_FNC_GetVehicleTurrets

  # EXAMPLE #
    _turrets = ("B_MRAP_01_hmg_F") call CTI_CO_FNC_GetVehicleTurrets
	  -> Returns: [[0]]
	 _turrets = ("O_MBT_01_F") call CTI_CO_FNC_GetVehicleTurrets
	  -> Returns: [[[0],"Commander"],[[1],"Gunner"]]

  # VIOC crew_fix #
	Lo usan la compra de la IA (Server_HandleAIPurchase.sqf: precio y tripulacion), la del jugador (CTI_UNIT_TURRETS, via
	Common\Config\Units\Get_DetailedTurrets.sqf: iconos, precio y tripulacion del menu de compra) y VIOC_ai_transport.sqf.
	El formato de salida no cambia: [[ruta]] o [[ruta], "Gunner"/"Commander"] (el primer primaryGunner y el primer
	primaryObserver, como antes). Parametro de lobby VIOC_CREW_FIX:
	  0 = el codigo original de abajo, sin cambios.
	  1 = (por defecto) solo la tripulacion del vehiculo, la misma que pone el editor. En los dos niveles se saltan:
	      - entradas de Turrets que no son clases (CUP M1A1: particlesPos/particlesDir; el original las contaba como torretas
	        y creaba 2 tripulantes sin asiento), y la ruta cuenta solo clases, como el motor;
	      - torretas con hasGunner = 0 (sin puesto);
	      - torretas dontCreateAI: puestos de pasajero FFV (CargoTurret) y puestos alternos del mod (M1 RHS/CUP: ametralladora
	        del jefe y del cargador, CROWS, GPSE; Stryker M1127/M1134, M1165 GMV, T-72 RHS), que RHS y CUP bloquean con
	        lockTurret en su script init: el original creaba ahi tripulantes que se quedaban de pie fuera.
	      isPersonTurret NO se usa para saltar: el jefe y el cargador del M1, el artillero del M1A1 de CUP y el jefe del
	      Stryker tienen isPersonTurret = 1 (arma personal asomado) y son tripulacion.
	  2 = como 1, pero conserva los puestos dontCreateAI que no son FFV (los que el mod bloquea no logran subir y la red de
	      seguridad de VIOC_crew_fix.sqf los borra y devuelve su precio).
*/

private ["_classname", "_config", "_config_sub", "_found_commander", "_found_gunner", "_get", "_skip", "_turrets", "_mode", "_turret_main", "_turret_sub", "_roleFound", "_fnc_skip", "_n1", "_n2"];

_classname = _this;
if (_classname isEqualType objNull) then {_classname = typeOf _classname};
_found_gunner = false;
_found_commander = false;
_mode = missionNamespace getVariable ["VIOC_CREW_FIX", 1];
if !(_mode isEqualType 0) then {_mode = 1};

_turrets = [];
_config = configFile >> "CfgVehicles" >> _classname >> "turrets";

//--- VIOC_CREW_FIX = 0: codigo original (BECTI, revision 31-03-2015)
if (_mode <= 0) exitWith {
	for '_i' from 0 to (count _config)-1 do {
		_turret_main = _config select _i;

		_get = [[_i]];
		_roleFound = false;
		_skip = false;
		if !(_found_gunner) then { if (getNumber (_turret_main >> "primaryGunner") > 0) then {_found_gunner = true; _roleFound = true; _get = [[_i], "Gunner"];}};
		if (!_found_commander && !_roleFound) then { if (getNumber (_turret_main >> "primaryObserver") > 0) then {_found_commander = true; _get = [[_i], "Commander"];}};
		if ("CargoTurret" in ([_turret_main,true] call BIS_fnc_returnParents)) then {_skip = true}; //--- Ignore FFV positions
		if !(_skip) then { _turrets = _turrets + [_get]};

		_config_sub = _turret_main >> "turrets";
		for '_j' from 0 to (count _config_sub) -1 do {
			_turret_sub = _config_sub select _j;

			_get = [[_i, _j]];
			_roleFound = false;
			if !(_found_gunner) then { if (getNumber (_turret_sub >> "primaryGunner") > 0) then {_found_gunner = true; _roleFound = true; _get = [[_i, _j], "Gunner"];}};
			if (!_found_commander && !_roleFound) then { if (getNumber (_turret_sub >> "primaryObserver") > 0) then {_found_commander = true; _get = [[_i, _j], "Commander"];}};
			_turrets = _turrets + [_get];
		};
	};
	_turrets
};

//--- VIOC crew_fix: [config de la torreta] -> true si no es un asiento de tripulacion
_fnc_skip = {
	params ["_t"];
	if !(isClass _t) exitWith {true}; //--- valor suelto dentro de Turrets
	if (isNumber (_t >> "hasGunner") && {getNumber (_t >> "hasGunner") == 0}) exitWith {true}; //--- torreta sin puesto
	private _dca = getNumber (_t >> "dontCreateAI") > 0;
	if (_dca && {(([_t, true] call BIS_fnc_returnParents) findIf {_x == "CargoTurret"}) >= 0}) exitWith {true}; //--- FFV de pasajero
	(_mode == 1) && _dca //--- puesto alterno del mod (el editor tampoco pone IA ahi)
};

_n1 = -1;
for '_i' from 0 to (count _config)-1 do {
	_turret_main = _config select _i;
	if (isClass _turret_main) then {
		_n1 = _n1 + 1; //--- la ruta del motor cuenta solo las clases
		if !([_turret_main] call _fnc_skip) then {
			_get = [[_n1]];
			_roleFound = false;
			if !(_found_gunner) then { if (getNumber (_turret_main >> "primaryGunner") > 0) then {_found_gunner = true; _roleFound = true; _get = [[_n1], "Gunner"];}};
			if (!_found_commander && !_roleFound) then { if (getNumber (_turret_main >> "primaryObserver") > 0) then {_found_commander = true; _get = [[_n1], "Commander"];}};
			_turrets pushBack _get;
		};

		_config_sub = _turret_main >> "turrets";
		_n2 = -1;
		for '_j' from 0 to (count _config_sub)-1 do {
			_turret_sub = _config_sub select _j;
			if (isClass _turret_sub) then {
				_n2 = _n2 + 1;
				if !([_turret_sub] call _fnc_skip) then {
					_get = [[_n1, _n2]];
					_roleFound = false;
					if !(_found_gunner) then { if (getNumber (_turret_sub >> "primaryGunner") > 0) then {_found_gunner = true; _roleFound = true; _get = [[_n1, _n2], "Gunner"];}};
					if (!_found_commander && !_roleFound) then { if (getNumber (_turret_sub >> "primaryObserver") > 0) then {_found_commander = true; _get = [[_n1, _n2], "Commander"];}};
					_turrets pushBack _get;
				};
			};
		};
	};
};

_turrets

/*
	VIOC_crew_fix.sqf - parche crew_fix de VIOC (2026-10-16). No es del autor de la mision.
	Alias: VIOC_CF_fnc_watchCrew (compileFinal en Common\Init\Init_Common.sqf, en todas las maquinas).

	Red de seguridad de la compra de vehiculos con tripulacion. La llaman con spawn, justo despues de crear la tripulacion:
	  - la compra del jugador (Client\Functions\Client_OnPurchaseOrderReceived.sqf, en la maquina del jugador);
	  - la compra de la IA (Server\Functions\Server_HandleAIPurchase.sqf, en el servidor).
	Espera 3 s y cada tripulante de la lista que sigue a pie (no logro subir: asiento que no existe o que el mod bloquea con
	lockTurret) se borra, y se devuelve al mismo pagador lo que la mision cobro por el (precio de la unidad de tripulacion por
	puesto; en la IA con la misma rebaja /100 y el mismo recargo de base avanzada que el cobro).
	Nunca toca: jugadores, unidades que no estan en la lista (la infanteria comprada aparte nunca entra en ella), unidades de
	otra maquina, ni nada si el vehiculo ya no existe o fue destruido en esos 3 s.
	Parametro de lobby VIOC_CREW_FIX: 0 = no hace nada (como el original).

	Parametros: [vehiculo, tripulantes creados, pagador (grupo, como en CTI_CO_FNC_ChangeFunds), bando, precio por tripulante,
	             origen ("jugador" o "IA", para el aviso y el registro)]
*/
params [["_veh", objNull, [objNull]], ["_crew", [], [[]]], ["_payer", grpNull], ["_side", sideUnknown, [sideUnknown]], ["_price", 0, [0]], ["_from", "", [""]]];

if ((missionNamespace getVariable ["VIOC_CREW_FIX", 1]) isEqualTo 0) exitWith {};
_crew = _crew select {!isNil "_x" && {_x isEqualType objNull}};
if (count _crew == 0) exitWith {};

sleep 3;

if (isNull _veh || {!alive _veh}) exitWith {};

private _gone = [];
{
	if (!isNull _x && {alive _x} && {!isPlayer _x} && {local _x} && {isNull objectParent _x}) then {
		_gone pushBack (typeOf _x);
		deleteVehicle _x;
	};
} forEach _crew;

if (count _gone == 0) exitWith {};

private _refund = round ((count _gone) * _price);
if (_refund > 0 && {!isNil "CTI_CO_FNC_ChangeFunds"}) then {[_payer, _side, _refund] call CTI_CO_FNC_ChangeFunds};

diag_log format ["VIOC crew_fix: compra %1 de %2: %3 tripulante(s) sin asiento retirado(s) %4; reembolso %5", _from, typeOf _veh, count _gone, _gone, _refund];
if (hasInterface && {_from == "jugador"}) then {
	systemChat format ["VIOC: %1 tripulante(s) de tu %2 no tenian asiento y se retiraron (se te devolvieron $%3).", count _gone, getText (configFile >> "CfgVehicles" >> typeOf _veh >> "displayName"), _refund];
};

//--- VIOC crew_fix: con VIOC_CREW_FIX > 0 la lista de torretas de la compra del jugador (CTI_UNIT_TURRETS: iconos, precio y
//--- tripulacion del menu de compra) sale de la funcion corregida de la IA (Common_GetVehicleTurrets.sqf). Con 0, lo original.
if (!isNil "CTI_CO_FNC_GetVehicleTurrets" && {(missionNamespace getVariable ["VIOC_CREW_FIX", 1]) isEqualType 0} && {(missionNamespace getVariable ["VIOC_CREW_FIX", 1]) > 0}) exitWith {_this call CTI_CO_FNC_GetVehicleTurrets};

//--- VIOC crew_fix: red de seguridad: a los 3 s, el tripulante que no logro subir se borra y se devuelve su precio (ver VIOC_crew_fix.sqf)
if ((missionNamespace getVariable ["VIOC_CREW_FIX", 1]) isEqualType 0 && {(missionNamespace getVariable ["VIOC_CREW_FIX", 1]) > 0} && {!isNil "VIOC_CF_fnc_watchCrew"}) then {
	private _vioc_cf_type = switch (true) do { case (_model isKindOf "Tank"): {"Crew"}; case (_model isKindOf "Air"): {"Pilot"}; default {"Soldier"}};
	private _vioc_cf_var = missionNamespace getVariable [format ["CTI_%1_%2", CTI_P_SideJoined, _vioc_cf_type], ""];
	if (_model isKindOf "Ship" && {getText (configFile >> "CfgVehicles" >> _model >> "simulation") == "submarinex"}) then {_vioc_cf_var = missionNamespace getVariable [format ["CTI_%1_Diver", CTI_P_SideJoined], ""]};
	private _vioc_cf_info = if (_vioc_cf_var isEqualType "" && {_vioc_cf_var != ""}) then {missionNamespace getVariable [_vioc_cf_var, []]} else {[]};
	private _vioc_cf_price = if (_vioc_cf_info isEqualType [] && {count _vioc_cf_info > 2}) then {_vioc_cf_info select 2} else {0}; //--- lo que se cobro por puesto
	if (!isNil "_vioc_fb" && {(_vioc_fb param [0, ""]) isEqualTo "OK"}) then {_vioc_cf_price = _vioc_cf_price * (_vioc_fb param [3, 1])}; //--- recargo de base avanzada
	[_vehicle, +_units, _req_buyer, CTI_P_SideJoined, _vioc_cf_price, "jugador"] spawn VIOC_CF_fnc_watchCrew;
};

//--- VIOC crew_fix: red de seguridad: a los 3 s, el tripulante que no logro subir se borra y se devuelve su precio (ver VIOC_crew_fix.sqf)
if ((missionNamespace getVariable ["VIOC_CREW_FIX", 1]) isEqualType 0 && {(missionNamespace getVariable ["VIOC_CREW_FIX", 1]) > 0} && {!isNil "VIOC_CF_fnc_watchCrew"}) then {
	private _vioc_cf_type = switch (true) do { case (_model isKindOf "Tank"): {"Crew"}; case (_model isKindOf "Air"): {"Pilot"}; default {"Soldier"}};
	private _vioc_cf_var = missionNamespace getVariable [format ["CTI_%1_%2", _req_side, _vioc_cf_type], ""];
	private _vioc_cf_info = if (_vioc_cf_var isEqualType "" && {_vioc_cf_var != ""}) then {missionNamespace getVariable [_vioc_cf_var, []]} else {[]};
	private _vioc_cf_price = if (_vioc_cf_info isEqualType [] && {count _vioc_cf_info > 2}) then {_vioc_cf_info select 2} else {0}; //--- lo que se cobro por puesto
	if (CTI_AI_SKILL_BASE < 0.40) then {_vioc_cf_price = _vioc_cf_price / 100}; //--- la misma rebaja de la IA que el cobro
	if (!isNil "_vioc_fb" && {(_vioc_fb param [0, ""]) isEqualTo "OK"}) then {_vioc_cf_price = _vioc_cf_price * (_vioc_fb param [3, 1])}; //--- recargo de base avanzada
	[_vehicle, _vioc_cf_crew, _req_buyer, _req_side, _vioc_cf_price, "IA"] spawn VIOC_CF_fnc_watchCrew;
};

class VIOC_CREW_FIX {
	title = "VIOC: Tripulacion al comprar vehiculos (solo asientos reales: sin soldados de mas que se quedan de pie fuera, p. ej. en el M1 Abrams)";
	values[] = {0,1,2};
	texts[] = {"No (original)","Si: la tripulacion del vehiculo, como en el editor","Si, y tambien los puestos alternos del mod (los bloqueados se retiran)"};
	default = 1;
};
